package com.medicaps.sms.controller;

import com.medicaps.sms.model.*; import com.medicaps.sms.repository.*;
import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid;
import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.web.bind.annotation.*; import java.time.*; import java.math.*; import java.util.*; import java.util.stream.*;

@RestController @RequestMapping("/api")
public class ApiController {
 @Autowired UserRepository users; @Autowired StudentRepository students; @Autowired TeacherRepository teachers; @Autowired CourseRepository courses; @Autowired SubjectRepository subjects; @Autowired AttendanceRepository attendance; @Autowired MarkRepository marks; @Autowired FeeRepository fees; @Autowired BCryptPasswordEncoder encoder;
 private String role(HttpSession s){Object r=s.getAttribute("role");return r==null?null:r.toString();}
 private String username(HttpSession s){Object r=s.getAttribute("username");return r==null?null:r.toString();}
 private ResponseEntity<?> deny(){return ResponseEntity.status(403).body(Map.of("message","You do not have permission to perform this action."));}
 private boolean has(HttpSession s,String... roles){String r=role(s);return r!=null&&Arrays.asList(roles).contains(r);}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,String> body,HttpSession s){String un=body.getOrDefault("username","");String pw=body.getOrDefault("password","");User u=users.findByUsername(un).orElse(null);if(u==null||!u.isActive()||!encoder.matches(pw,u.getPassword()))return ResponseEntity.status(401).body(Map.of("message","Invalid username or password"));s.setAttribute("username",u.getUsername());s.setAttribute("role",u.getRole());s.setAttribute("name",u.getName());return ResponseEntity.ok(Map.of("username",u.getUsername(),"name",u.getName()==null?"":u.getName(),"role",u.getRole()));}
 @PostMapping("/auth/logout") public ResponseEntity<?> logout(HttpSession s){s.invalidate();return ResponseEntity.ok(Map.of("message","Logged out"));}
 @GetMapping("/auth/me") public ResponseEntity<?> me(HttpSession s){if(role(s)==null)return ResponseEntity.status(401).body(Map.of("message","Not logged in"));return ResponseEntity.ok(Map.of("username",username(s),"role",role(s),"name",s.getAttribute("name")));}
 @PostMapping("/auth/users") public ResponseEntity<?> createUser(@RequestBody Map<String,String> b,HttpSession s){if(!has(s,"ADMIN"))return deny();if(users.findByUsername(b.get("username")).isPresent())return ResponseEntity.badRequest().body(Map.of("message","Username already exists"));User u=new User();u.setUsername(b.get("username"));u.setName(b.get("name"));u.setEmail(b.get("email"));u.setRole(b.getOrDefault("role","STUDENT").toUpperCase());u.setPassword(encoder.encode(b.get("password")));User saved=users.save(u);return ResponseEntity.ok(Map.of("id",saved.getId(),"username",saved.getUsername(),"role",saved.getRole(),"name",saved.getName()));}
 @GetMapping("/auth/users") public ResponseEntity<?> listUsers(HttpSession s){if(!has(s,"ADMIN"))return deny();return ResponseEntity.ok(users.findAll().stream().map(u->Map.of("id",u.getId(),"username",u.getUsername(),"name",u.getName()==null?"":u.getName(),"email",u.getEmail()==null?"":u.getEmail(),"role",u.getRole(),"active",u.isActive())).toList());}
 @GetMapping("/dashboard") public ResponseEntity<?> dashboard(HttpSession s){if(role(s)==null)return ResponseEntity.status(401).build();Map<String,Object> m=new LinkedHashMap<>();m.put("role",role(s));m.put("totalStudents",students.count());m.put("totalTeachers",teachers.count());m.put("totalCourses",courses.count());m.put("totalAttendance",attendance.count());m.put("totalFees",fees.findAll().stream().map(Fee::getTotalFees).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add));m.put("paidFees",fees.findAll().stream().map(Fee::getPaidFees).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add));if("STUDENT".equals(role(s))){Student st=students.findByStudentId(username(s)).orElse(null);if(st!=null){m.put("student",st);m.put("myAttendance",attendance.findByStudentId(st.getStudentId()));m.put("myMarks",marks.findByStudentId(st.getStudentId()));m.put("myFees",fees.findByStudentId(st.getStudentId()).orElse(null));}}return ResponseEntity.ok(m);}
 @GetMapping("/students") public ResponseEntity<?> getStudents(@RequestParam(required=false) String q,HttpSession s){if(!has(s,"ADMIN","TEACHER"))return deny();if(q==null||q.isBlank())return ResponseEntity.ok(students.findAll());List<Student> result=new ArrayList<>();students.findByStudentId(q).ifPresent(result::add);students.findByFullNameContainingIgnoreCase(q).forEach(x->{if(!result.contains(x))result.add(x);});return ResponseEntity.ok(result);}
 @PostMapping("/students") public ResponseEntity<?> addStudent(@RequestBody Student x,HttpSession s){if(!has(s,"ADMIN"))return deny();if(x.getStudentId()==null||x.getStudentId().isBlank()||x.getFullName()==null||x.getFullName().isBlank())return ResponseEntity.badRequest().body(Map.of("message","Student ID and full name are required"));if(students.findByStudentId(x.getStudentId()).isPresent())return ResponseEntity.badRequest().body(Map.of("message","Student ID already exists"));return ResponseEntity.ok(students.save(x));}
 @PutMapping("/students/{id}") public ResponseEntity<?> updateStudent(@PathVariable Long id,@RequestBody Student x,HttpSession s){if(!has(s,"ADMIN"))return deny();Student old=students.findById(id).orElse(null);if(old==null)return ResponseEntity.notFound().build();old.setFullName(x.getFullName());old.setEmail(x.getEmail());old.setPhone(x.getPhone());old.setDepartment(x.getDepartment());old.setCourse(x.getCourse());old.setSemester(x.getSemester());old.setAdmissionDate(x.getAdmissionDate());old.setGender(x.getGender());old.setAddress(x.getAddress());return ResponseEntity.ok(students.save(old));}
 @DeleteMapping("/students/{id}") public ResponseEntity<?> deleteStudent(@PathVariable Long id,HttpSession s){if(!has(s,"ADMIN"))return deny();students.deleteById(id);return ResponseEntity.ok(Map.of("message","Student deleted"));}
 @GetMapping("/teachers") public ResponseEntity<?> getTeachers(HttpSession s){if(!has(s,"ADMIN","TEACHER"))return deny();return ResponseEntity.ok(teachers.findAll());}
 @PostMapping("/teachers") public ResponseEntity<?> addTeacher(@RequestBody Teacher x,HttpSession s){if(!has(s,"ADMIN"))return deny();return ResponseEntity.ok(teachers.save(x));}
 @GetMapping("/courses") public ResponseEntity<?> getCourses(HttpSession s){if(role(s)==null)return ResponseEntity.status(401).build();return ResponseEntity.ok(courses.findAll());}
 @PostMapping("/courses") public ResponseEntity<?> addCourse(@RequestBody Course x,HttpSession s){if(!has(s,"ADMIN"))return deny();return ResponseEntity.ok(courses.save(x));}
 @GetMapping("/subjects") public ResponseEntity<?> getSubjects(HttpSession s){if(role(s)==null)return ResponseEntity.status(401).build();return ResponseEntity.ok(subjects.findAll());}
 @PostMapping("/subjects") public ResponseEntity<?> addSubject(@RequestBody Subject x,HttpSession s){if(!has(s,"ADMIN"))return deny();return ResponseEntity.ok(subjects.save(x));}
 @GetMapping("/attendance") public ResponseEntity<?> getAttendance(@RequestParam(required=false) String studentId,HttpSession s){if(!has(s,"ADMIN","TEACHER","STUDENT"))return deny();if("STUDENT".equals(role(s)))studentId=username(s);return ResponseEntity.ok(studentId==null?attendance.findAll():attendance.findByStudentId(studentId));}
 @PostMapping("/attendance") public ResponseEntity<?> saveAttendance(@RequestBody List<Attendance> rows,HttpSession s){if(!has(s,"TEACHER","ADMIN"))return deny();for(Attendance a:rows){if(a.getStudentId()==null||a.getAttendanceDate()==null||(a.getStatus()==null||!List.of("PRESENT","ABSENT").contains(a.getStatus().toUpperCase())))return ResponseEntity.badRequest().body(Map.of("message","Invalid attendance row"));a.setStatus(a.getStatus().toUpperCase());a.setMarkedBy(username(s));}return ResponseEntity.ok(attendance.saveAll(rows));}
 @GetMapping("/marks") public ResponseEntity<?> getMarks(@RequestParam(required=false) String studentId,HttpSession s){if(role(s)==null)return ResponseEntity.status(401).build();if("STUDENT".equals(role(s)))studentId=username(s);return ResponseEntity.ok(studentId==null?marks.findAll():marks.findByStudentId(studentId));}
 @PostMapping("/marks") public ResponseEntity<?> saveMark(@RequestBody Mark x,HttpSession s){if(!has(s,"TEACHER","ADMIN"))return deny();if(x.getObtainedMarks()==null||x.getMaximumMarks()==null||x.getObtainedMarks()<0||x.getMaximumMarks()<=0||x.getObtainedMarks()>x.getMaximumMarks())return ResponseEntity.badRequest().body(Map.of("message","Marks must be between 0 and maximum marks"));double p=x.getObtainedMarks()/x.getMaximumMarks()*100;x.setGrade(p>=90?"A+":p>=80?"A":p>=70?"B":p>=60?"C":p>=50?"D":"F");return ResponseEntity.ok(marks.save(x));}
 @PutMapping("/marks/{id}") public ResponseEntity<?> updateMark(@PathVariable Long id,@RequestBody Mark x,HttpSession s){if(!has(s,"TEACHER","ADMIN"))return deny();Mark old=marks.findById(id).orElse(null);if(old==null)return ResponseEntity.notFound().build();if(x.getObtainedMarks()==null||x.getMaximumMarks()==null||x.getObtainedMarks()<0||x.getMaximumMarks()<=0||x.getObtainedMarks()>x.getMaximumMarks())return ResponseEntity.badRequest().body(Map.of("message","Marks must be between 0 and maximum marks"));old.setObtainedMarks(x.getObtainedMarks());old.setMaximumMarks(x.getMaximumMarks());old.setSubject(x.getSubject());old.setCourse(x.getCourse());old.setSemester(x.getSemester());double p=x.getObtainedMarks()/x.getMaximumMarks()*100;old.setGrade(p>=90?"A+":p>=80?"A":p>=70?"B":p>=60?"C":p>=50?"D":"F");return ResponseEntity.ok(marks.save(old));}
 @GetMapping("/fees") public ResponseEntity<?> getFees(HttpSession s){if(role(s)==null)return ResponseEntity.status(401).build();if("STUDENT".equals(role(s)))return ResponseEntity.ok(fees.findByStudentId(username(s)).stream().toList());return ResponseEntity.ok(fees.findAll());}
 @PostMapping("/fees") public ResponseEntity<?> saveFee(@RequestBody Fee x,HttpSession s){if(!has(s,"ADMIN"))return deny();if(x.getStudentId()==null||x.getStudentId().isBlank()||x.getTotalFees()==null||x.getPaidFees()==null||x.getTotalFees().signum()<0||x.getPaidFees().signum()<0||x.getPaidFees().compareTo(x.getTotalFees())>0)return ResponseEntity.badRequest().body(Map.of("message","Invalid fee amounts"));x.setPendingFees(x.getTotalFees().subtract(x.getPaidFees()));x.setUpdatedAt(LocalDate.now());Fee old=fees.findByStudentId(x.getStudentId()).orElse(null);if(old!=null)x.setId(old.getId());return ResponseEntity.ok(fees.save(x));}
 @GetMapping("/reports/summary") public ResponseEntity<?> reports(HttpSession s){if(!has(s,"ADMIN","TEACHER"))return deny();long present=attendance.findAll().stream().filter(a->"PRESENT".equals(a.getStatus())).count();long total=attendance.count();return ResponseEntity.ok(Map.of("students",students.count(),"teachers",teachers.count(),"attendanceRecords",total,"presentRecords",present,"attendanceRate",total==0?0:Math.round(present*100.0/total),"fees",fees.findAll()));}
}
